-- Read-only Grafana uses the same versioned primitive dictionary as the backend.
CREATE TABLE app.trace_reference_definition(metric_id VARCHAR(96) PRIMARY KEY,definition JSONB NOT NULL);
REVOKE ALL ON app.trace_reference_definition FROM incidents_app;
GRANT SELECT ON app.trace_reference_definition TO incidents_app;
INSERT INTO app.trace_reference_definition VALUES ('volte.attempts','{"metricId":"volte.attempts","displayName":"VoLTE call attempts","domain":"VOLTE","unit":"COUNT","population":"Deduplicated eligible originating setup attempts under the declared call/leg policy. Reference cities are disjoint fictional cohorts.","aggregation":"COUNT_SUM","primitiveFields":["count"],"scopeDimensions":["cityId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"SUPPORTED","fields":["voice_attempts"],"reason":null},"histogramSchema":null}'::jsonb);
