INSERT INTO app.trace_reference_definition VALUES ('transport.traffic','{"metricId":"transport.traffic","displayName":"Directional carried traffic","domain":"TRANSPORT","unit":"GBPS","population":"Directional carried bits / valid elapsed seconds / 1e9; time-weight each observed rate.","aggregation":"TIME_WEIGHTED_MEAN","primitiveFields":["weightedSum","validSeconds"],"scopeDimensions":["linkId","directionId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"APPROXIMATION","fields":["traffic_gbps"],"reason":"Reference rate sample assumes 300 valid seconds and A-to-B direction; byte deltas/reset epochs absent."},"histogramSchema":null}'::jsonb);
INSERT INTO app.trace_reference_definition VALUES ('transport.volume','{"metricId":"transport.volume","displayName":"Transferred data volume","domain":"TRANSPORT","unit":"BYTES","population":"Valid byte deltas across time at one directional observation boundary; do not count successive hops as unique traffic.","aggregation":"COUNT_SUM","primitiveFields":["count"],"scopeDimensions":["linkId","directionId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"APPROXIMATION","fields":["traffic_gbps"],"reason":"Derived estimate traffic_gbps * 1e9 / 8 * 300; measured byte counters and valid-time evidence absent."},"histogramSchema":null}'::jsonb);
INSERT INTO app.trace_reference_definition VALUES ('transport.effectiveCapacity','{"metricId":"transport.effectiveCapacity","displayName":"Effective directional capacity","domain":"TRANSPORT","unit":"GBPS","population":"Operational directional capacity valid at the endpoint; retain changes, never substitute nominal capacity after reduction.","aggregation":"SNAPSHOT_LAST","primitiveFields":["value","snapshotAt"],"scopeDimensions":["linkId","directionId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"APPROXIMATION","fields":["effective_capacity_gbps"],"reason":"Slot-level gauge available; exact validity intervals/source authority absent."},"histogramSchema":null}'::jsonb);
INSERT INTO app.trace_reference_definition VALUES ('transport.link.utilization','{"metricId":"transport.link.utilization","displayName":"Link utilization","domain":"TRANSPORT","unit":"PERCENT","population":"100 * directional carried traffic / contemporaneous positive effective capacity, averaged over valid seconds.","aggregation":"TIME_WEIGHTED_MEAN","primitiveFields":["weightedSum","validSeconds"],"scopeDimensions":["linkId","directionId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"APPROXIMATION","fields":["traffic_gbps","effective_capacity_gbps"],"reason":"Reference endpoint ratio supported; mean requires explicit 300-second validity assumption. Reference linkSeries displays peak, not mean."},"histogramSchema":null}'::jsonb);
INSERT INTO app.trace_reference_definition VALUES ('transport.link.utilization.peak','{"metricId":"transport.link.utilization.peak","displayName":"Peak link utilization","domain":"TRANSPORT","unit":"PERCENT","population":"Maximum of contemporaneous 100 * directional carried traffic / positive effective capacity across valid source slots and selected declared link-direction scopes. This maximum is distinct from temporal mean and never sums link utilizations.","aggregation":"MAXIMUM","primitiveFields":["max"],"scopeDimensions":["linkId","directionId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"APPROXIMATION","fields":["traffic_gbps","effective_capacity_gbps"],"reason":"Reference linkSeries uses maximum per-slot utilization across selected scoped links. Source validity is assumed for supplied slots; A-to-B only."},"histogramSchema":null}'::jsonb);
INSERT INTO app.trace_reference_definition VALUES ('transport.packetLoss','{"metricId":"transport.packetLoss","displayName":"Packet loss","domain":"TRANSPORT","unit":"PERCENT","population":"Lost / expected packets for the same declared probe/path/interface and direction.","aggregation":"RATIO_OF_SUMS","primitiveFields":["numerator","denominator"],"scopeDimensions":["linkId","directionId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"REQUIRES_ADDITIONAL_PRIMITIVES","fields":["loss_pct"],"reason":"Only loss percentage exists; lost/expected counts absent. Use separately labelled snapshot/worst-loss reference; never invent counts."},"histogramSchema":null}'::jsonb);
INSERT INTO app.trace_reference_definition VALUES ('transport.rtt.mean','{"metricId":"transport.rtt.mean","displayName":"Round-trip latency mean","domain":"TRANSPORT","unit":"MILLISECONDS","population":"Qualifying RTT probe elapsed sum / probe count on the same path.","aggregation":"WEIGHTED_MEAN","primitiveFields":["sum","count"],"scopeDimensions":["linkId","directionId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"REQUIRES_ADDITIONAL_PRIMITIVES","fields":["rtt_ms"],"reason":"Scalar RTT only; probe sum/count absent."},"histogramSchema":null}'::jsonb);
INSERT INTO app.trace_reference_definition VALUES ('transport.rtt.snapshot','{"metricId":"transport.rtt.snapshot","displayName":"Round-trip latency snapshot","domain":"TRANSPORT","unit":"MILLISECONDS","population":"Illustrative RTT scalar at selected link endpoint observation.","aggregation":"SNAPSHOT_LAST","primitiveFields":["value","snapshotAt"],"scopeDimensions":["linkId","directionId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"APPROXIMATION","fields":["rtt_ms"],"reason":"Probe/path identity absent; series uses worst-scoped RTT, not probe-weighted mean."},"histogramSchema":null}'::jsonb);
