INSERT INTO app.trace_reference_definition VALUES ('transport.interfaceErrors','{"metricId":"transport.interfaceErrors","displayName":"Interface error count","domain":"TRANSPORT","unit":"COUNT","population":"Valid nonnegative interface error deltas under declared counter/reset policy.","aggregation":"COUNT_SUM","primitiveFields":["count"],"scopeDimensions":["linkId","directionId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"APPROXIMATION","fields":["interface_errors"],"reason":"Illustrative per-slot counts; counter identity/reset epoch absent. Error rate requires independent frames/packets denominator."},"histogramSchema":null}'::jsonb);
