INSERT INTO app.trace_reference_definition VALUES ('sms.expired','{"metricId":"sms.expired","displayName":"Expired SMS","domain":"SMS","unit":"COUNT","population":"Unique final validity-expired messages by terminal completion time.","aggregation":"COUNT_SUM","primitiveFields":["count"],"scopeDimensions":["cityId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"REQUIRES_ADDITIONAL_PRIMITIVES","fields":["sms_expired"],"reason":"Reference sms_expired combines terminal negative outcomes; separate failure/expiry counters are absent."},"histogramSchema":null}'::jsonb);
INSERT INTO app.trace_reference_definition VALUES ('sms.finalizedSuccess','{"metricId":"sms.finalizedSuccess","displayName":"SMS finalized delivery success","domain":"SMS","unit":"PERCENT","population":"Delivered / (delivered + terminal failed + expired), by completion time, excluding pending; never same-window delivered/submitted.","aggregation":"RATIO_OF_SUMS","primitiveFields":["numerator","denominator"],"scopeDimensions":["cityId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"APPROXIMATION","fields":["sms_delivered","sms_expired"],"reason":"Map sms_expired once to combined terminal negatives, not separately to both failed and expired; lifecycle/cohort event IDs absent."},"histogramSchema":null}'::jsonb);
