INSERT INTO app.trace_reference_definition VALUES ('sms.oldestPending','{"metricId":"sms.oldestPending","displayName":"Oldest pending SMS age","domain":"SMS","unit":"SECONDS","population":"Maximum age across current pending messages at endpoint; empty fresh queue is zero.","aggregation":"SNAPSHOT_LAST","primitiveFields":["value","snapshotAt"],"scopeDimensions":["cityId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"APPROXIMATION","fields":["sms_oldest_seconds"],"reason":"Age derived synthetically from queue/submissions; not reconstructed per-message waiting time."},"histogramSchema":null}'::jsonb);
INSERT INTO app.trace_reference_definition VALUES ('sms.delay.mean','{"metricId":"sms.delay.mean","displayName":"SMS delivery delay mean","domain":"SMS","unit":"MILLISECONDS","population":"Delivered-message accepted-to-final-delivery elapsed milliseconds / valid delivered observation count.","aggregation":"WEIGHTED_MEAN","primitiveFields":["sum","count"],"scopeDimensions":["cityId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-sms-delay-ms-v1","reference":{"availability":"REQUIRES_ADDITIONAL_PRIMITIVES","fields":["sms_delay_hist"],"reason":"Elapsed sum absent; a histogram cannot establish exact mean. Target milliseconds are explicitly versioned."},"histogramSchema":null}'::jsonb);
INSERT INTO app.trace_reference_definition VALUES ('sms.delay.p95','{"metricId":"sms.delay.p95","displayName":"SMS delivery delay p95","domain":"SMS","unit":"MILLISECONDS","population":"Delivered-message delays; pool compatible seconds histogram bins, interpolate once then multiply by 1000. Excludes pending queue age.","aggregation":"HISTOGRAM_P95","primitiveFields":["histogram"],"scopeDimensions":["cityId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-sms-delay-ms-v1","reference":{"availability":"APPROXIMATION","fields":["sms_delay_hist"],"reason":"Bounded synthetic finite-bin estimate; explicit seconds-to-milliseconds conversion under trace-link-sms-delay-ms-v1."},"histogramSchema":{"version":"trace-link-sms-histogram-v1","unit":"SECONDS","representation":"NON_CUMULATIVE_FINITE_BINS","edges":[1,2,5,10,20,40,80,160,320]}}'::jsonb);
INSERT INTO app.trace_reference_definition VALUES ('sms.queueGrowth','{"metricId":"sms.queueGrowth","displayName":"SMS queue growth","domain":"SMS","unit":"COUNT","population":"End minus start pending queue; equals accepted minus delivered minus combined terminal negatives in one scope/window.","aggregation":"SNAPSHOT_DIFFERENCE","primitiveFields":["start","end"],"scopeDimensions":["cityId"],"minimumVolume":null,"qualityRequirements":["VALID_PRIMITIVES","EXPLICIT_COVERAGE","FRESH_SOURCE"],"policyVersion":"trace-link-kpi-v1","reference":{"availability":"APPROXIMATION","fields":["sms_queue","sms_submitted","sms_delivered","sms_expired"],"reason":"First CSV window lacks opening queue; supply explicit opening snapshot or return unavailable, never assume zero."},"histogramSchema":null}'::jsonb);
